{
  "name": "@metalbolicx/opencode-ponytail",
  "version": "4.8.4",
  "description": "Lazy senior dev mode for AI agents. The best code is the code you never wrote.",
  "keywords": [
    "opencode-plugin",
    "opencode",
    "ponytail",
    "pi-package",
    "pi",
    "skills",
    "qoder"
  ],
  "license": "MIT",
  "author": {
    "name": "MetalbolicX",
    "url": "https://github.com/MetalbolicX"
  },
  "homepage": "https://github.com/MetalbolicX/opencode-ponytail",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/MetalbolicX/opencode-ponytail.git"
  },
  "bugs": {
    "url": "https://github.com/MetalbolicX/opencode-ponytail/issues"
  },
  "bin": {
    "ponytail": "./cli.mjs"
  },
  "main": "./.opencode/plugins/ponytail.mjs",
  "exports": {
    ".": "./.opencode/plugins/ponytail.mjs",
    "./plugin": "./.opencode/plugins/ponytail.mjs"
  },
  "files": [
    "cli.mjs",
    "AGENTS.md",
    "hooks/",
    "skills/",
    ".opencode/",
    ".qoder/",
    ".qoder-plugin/",
    "pi-extension/",
    "scripts/uninstall.js",
    "assets/",
    "LICENSE"
  ],
  "engines": {
    "node": ">=20.0.0"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "1.17.18",
    "@types/node": "^22.0.0",
    "typescript": "^5.6.0"
  },
  "pi": {
    "extensions": [
      "./pi-extension/index.js"
    ],
    "skills": [
      "./skills"
    ]
  },
  "publishConfig": {
    "access": "public"
  },
  "scripts": {
    "test": "node --test tests/*.test.js && pnpm -r test",
    "typecheck": "tsc --noEmit",
    "build": "pnpm run typecheck && pnpm test"
  }
}

{
  "dependencies": {
    "@opencode-ai/plugin": "1.18.1"
  }
}

{
  "name": "ponytail-pi-extension-dev",
  "private": true,
  "type": "module",
  "scripts": {
    "test": "node --test ./test/*.test.js"
  }
}
